CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE ROLE anon NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticated NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE SCHEMA IF NOT EXISTS auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text);
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TABLE public.commercial_organizations(id uuid PRIMARY KEY,name text NOT NULL,logo_url text);
CREATE TABLE public.commercial_organization_members(organization_id uuid NOT NULL,user_id uuid NOT NULL,state text NOT NULL,role text NOT NULL);
CREATE TABLE public.commercial_organization_locations(id uuid PRIMARY KEY,organization_id uuid NOT NULL,state text NOT NULL,latitude numeric,longitude numeric);
CREATE TABLE public.commercial_activities(id uuid PRIMARY KEY,organization_id uuid NOT NULL,activity_type text NOT NULL);
CREATE TABLE public.commercial_customers(id uuid PRIMARY KEY,organization_id uuid NOT NULL,auth_user_id uuid,state text NOT NULL DEFAULT 'active');
CREATE TABLE public.commercial_audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,actor_user_id uuid,action text,entity_type text,entity_id text,metadata jsonb DEFAULT '{}'::jsonb);
